rollback.sql:
DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM dinamica d WHERE d.instrumento_id IS NULL
               AND NOT EXISTS (SELECT 1 FROM dinamica_instrumento di WHERE di.dinamica_id = d.id)) THEN
        RAISE EXCEPTION 'Há Dinâmicas sem Instrumento de início nem Instrumentos abrangidos: associe-as ou apague-as antes de repor dinamica.instrumento_id NOT NULL.';
    END IF;
    UPDATE dinamica d SET instrumento_id = (SELECT di.instrumento_id FROM dinamica_instrumento di
                                            WHERE di.dinamica_id = d.id
                                            ORDER BY di.instrumento_id LIMIT 1)
    WHERE d.instrumento_id IS NULL;
END $$;
